import{_ as a,o as t,c as r,a2 as i}from"./chunks/framework.BjkiRu3Q.js";const u=JSON.parse('{"title":"Security, Privacy & GDPR","description":"","frontmatter":{},"headers":[],"relativePath":"security-privacy/index.md","filePath":"security-privacy/index.md"}'),n={name:"security-privacy/index.md"};function o(s,e,c,d,l,p){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="security-privacy-gdpr" tabindex="-1">Security, Privacy &amp; GDPR <a class="header-anchor" href="#security-privacy-gdpr" aria-label="Permalink to &quot;Security, Privacy &amp; GDPR&quot;">​</a></h1><p>TransferBook+ processes information used to arrange and operate transportation services. This guide explains security practices and privacy readiness for transportation companies, authorized staff and hosting teams.</p><div class="warning custom-block"><p class="custom-block-title">Scope and evidence</p><p>This is operational guidance, not a privacy notice, data processing agreement, security certification or guarantee of GDPR compliance. Existing Wiki API and role descriptions use the v0.7.9 source-reviewed reference. Confirm controls in the exact approved release and deployment before relying on them. The recommendations below are not assertions that all controls are implemented.</p></div><h2 id="accounts-and-company-boundaries" tabindex="-1">Accounts and company boundaries <a class="header-anchor" href="#accounts-and-company-boundaries" aria-label="Permalink to &quot;Accounts and company boundaries&quot;">​</a></h2><p>The reference documentation describes RS256 bearer-token verification, independent membership and permission checks, and roles for company administrators, dispatchers, drivers and viewers. A selected company identifier is not itself authorization. Driver access must be restricted to authorized assignments. See <a href="/developers/authentication.html">authentication and tenant access</a> and <a href="/developers/permissions.html">roles and permissions</a>.</p><ul><li>Assign individual accounts and the minimum permissions needed. Remove access promptly when staff leave or responsibilities change.</li><li>Use strong unique credentials, device locking and current browsers. Confirm session expiry, logout and account recovery on the accepted release. Require stronger authentication where supported and appropriate to risk.</li><li>Keep operator credentials and tokens out of public booking pages, screenshots and support tickets.</li><li>Test server-side company isolation, including direct API requests and cross-company object access, rather than relying on hidden interface elements.</li></ul><h2 id="passenger-driver-and-payment-information" tabindex="-1">Passenger, driver and payment information <a class="header-anchor" href="#passenger-driver-and-payment-information" aria-label="Permalink to &quot;Passenger, driver and payment information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Handling practice</th></tr></thead><tbody><tr><td>Passenger name, phone and optional email</td><td>Collect only what the booking or a justified purpose requires; never invent an email address</td></tr><tr><td>Pickup, destination, flight or vessel details</td><td>Share only with staff and partners who need them for the service</td></tr><tr><td>Driver identity, assignments and location</td><td>Restrict access; disclose purposes and assess whether monitoring is necessary and proportionate</td></tr><tr><td>VIP notes and booking history</td><td>Avoid unnecessary sensitive information, unrestricted free-text notes and unjustified profiling</td></tr><tr><td>Payment amount and reference</td><td>Use approved payment workflows; never enter card numbers or security codes into notes</td></tr></tbody></table><p>See <a href="/plus/passenger-information.html">passenger information</a>, <a href="/plus/payments-and-reconciliation.html">payments and reconciliation</a> and <a href="/integrations/payment-providers.html">payment provider readiness</a>. A provider listed in the interface is not evidence of live activation or PCI DSS certification. Confirm the provider&#39;s approved payment flow and the applicable compliance responsibilities.</p><p>Messaging and AI channels require separate approval, data-flow review and appropriate permissions. Transactional consent or a sandbox consent state is not marketing permission or proof of a GDPR lawful basis. Use only synthetic records in training and unapproved test environments. See <a href="/integrations/conversational-booking.html">conversational booking and consent</a>.</p><h2 id="gdpr-responsibilities" tabindex="-1">GDPR responsibilities <a class="header-anchor" href="#gdpr-responsibilities" aria-label="Permalink to &quot;GDPR responsibilities&quot;">​</a></h2><p>Where the GDPR applies, identify the controller, any joint controllers and processors for each processing purpose. A transportation company that determines why and how it uses passenger data will generally act as controller for that processing. A hosting or software provider processing on its behalf may act as processor; actual roles depend on the facts and agreements.</p><p>Before launch:</p><ul><li>Document processing purposes, categories, recipients and a lawful basis for each purpose. Assess special-category information separately if it is necessary.</li><li>Provide appropriate privacy information and establish arrangements for exercising individual rights.</li><li>Agree processor terms under Article 28 where applicable, including subprocessors, security and assistance obligations. Review international transfers under Chapter V.</li><li>Maintain required processing records and determine whether a data protection officer or impact assessment is required, particularly for high-risk processing such as systematic location monitoring.</li><li>Review marketing, tracking and messaging under applicable privacy and electronic communications rules; operational consent settings do not replace this assessment.</li></ul><h2 id="retention-and-individual-rights" tabindex="-1">Retention and individual rights <a class="header-anchor" href="#retention-and-individual-rights" aria-label="Permalink to &quot;Retention and individual rights&quot;">​</a></h2><p>Establish retention periods by purpose and applicable obligations, including financial records, operational logs, backups and support records. Delete or appropriately anonymize data when no longer justified, subject to lawful retention requirements. Do not assume a delete button permanently removes information from all systems or backups.</p><p>Provide a verified channel for access, rectification, erasure, restriction, portability, objection and other applicable rights. Requests are subject to the relevant conditions and exceptions. Under Article 12, controllers generally respond within one month; an extension of up to two further months may apply when justified, with notice within the initial month. Verify identity proportionately and protect other people&#39;s information.</p><p>Confirm the available export, correction, deletion and retention controls; use an approved administrative process where automation is not validated.</p><h2 id="audit-hosting-and-incident-response" tabindex="-1">Audit, hosting and incident response <a class="header-anchor" href="#audit-hosting-and-incident-response" aria-label="Permalink to &quot;Audit, hosting and incident response&quot;">​</a></h2><p>Security acceptance should cover:</p><ul><li>HTTPS configuration, patching, secret storage and database access restrictions.</li><li>Appropriate encryption and backup protections, restoration testing and documented recovery objectives.</li><li>Audit evidence for important actions, restricted log access, redaction of secrets and defined retention.</li><li>Monitoring, vulnerability remediation, tenant isolation tests and authorization checks.</li><li>A documented incident contact, containment plan, evidence preservation and escalation process.</li></ul><p>If a suspected breach occurs, report it promptly through the agreed secure channel, preserve relevant evidence and avoid distributing passenger records unnecessarily. Processors must inform the controller without undue delay after becoming aware of a personal data breach. Where notification is required, the controller must notify the competent supervisory authority without undue delay and, where feasible, within 72 hours of awareness. High-risk breaches generally also require communication to affected individuals without undue delay, subject to Article 34 exceptions.</p><p>See <a href="/installation/">Installation &amp; Deployment</a> for operational readiness and recovery planning.</p><h2 id="before-commercial-activation" tabindex="-1">Before commercial activation <a class="header-anchor" href="#before-commercial-activation" aria-label="Permalink to &quot;Before commercial activation&quot;">​</a></h2><p>Record the release tested, approved controls, responsible parties, unresolved risks and agreed privacy terms. Verify access isolation, audit coverage, retention and rights-handling procedures, provider agreements, incident contacts and recovery evidence. Do not market untested controls or describe the platform as certified or GDPR compliant solely on the basis of this guide.</p><h2 id="official-references" tabindex="-1">Official references <a class="header-anchor" href="#official-references" aria-label="Permalink to &quot;Official references&quot;">​</a></h2><ul><li><a href="https://eur-lex.europa.eu/eli/reg/2016/679/" target="_blank" rel="noreferrer">Regulation (EU) 2016/679 (GDPR)</a> — particularly Articles 5–6, 12–22, 28, 30, 32–35 and Chapter V.</li><li><a href="https://www.edpb.europa.eu/sme/learn-the-basics/data-controller-or-data-processor_en" target="_blank" rel="noreferrer">EDPB: Data controller or data processor</a></li><li><a href="https://www.edpb.europa.eu/sme/be-compliant/secure-personal-data_en" target="_blank" rel="noreferrer">EDPB: Secure personal data</a></li><li><a href="https://www.edpb.europa.eu/sme/be-compliant/respect-individuals-rights_en" target="_blank" rel="noreferrer">EDPB: Respect individuals’ rights</a></li><li><a href="https://www.edpb.europa.eu/sme/assess-the-risks/data-breaches_en" target="_blank" rel="noreferrer">EDPB: Data breaches</a></li></ul><p><a href="/el/security-privacy/">Ελληνικά</a></p>',28)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
